import {lucideIcons} from '/icons.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=n=>lucideIcons[n]||lucideIcons.apps;
const labels={STUDENT:'学生',TEACHER:'教师',LIBRARIAN:'图书管理员',PRINT_OPERATOR:'打印操作员',CANTEEN_MERCHANT:'食堂商户',CAMPUS_OPERATOR:'校园运营',SUPER_ADMIN:'超级管理员',PENDING:'待处理',READY:'待领取',FULFILLED:'已领取',CANCELLED:'已取消',REJECTED:'已拒绝',EXPIRED:'已过期',ACTIVE:'借阅中',RETURNED:'已归还',SUBMITTED:'待接单',ACCEPTED:'已接单',PROCESSING:'处理中',PREPARING:'备餐中',COMPLETED:'已完成',EXCEPTION:'异常',UNPAID:'未付款',PAID_OFFLINE:'已确认到店付款',SIMULATED_PAID:'模拟支付·未真实收款'};
let user=null, path=location.pathname, apps=[], file=null, cart={}, selectedStall=null;
const pendingWrites=new Map();
async function api(p,method='GET',body){
 const payload=body===undefined?undefined:JSON.stringify(body),write=method==='POST',fingerprint=[user?.id||'anonymous',p,payload].join(':');
 if(write&&!pendingWrites.has(fingerprint))pendingWrites.set(fingerprint,crypto.randomUUID());
 const r=await fetch('/api/v1/'+p,{method,headers:{'Content-Type':'application/json',...(write?{'Idempotency-Key':pendingWrites.get(fingerprint)}:{})},body:payload});
 let v;try{v=await r.json()}catch{throw Error('服务暂不可用，请重试；已提交的记录不会重复创建')}
 if(write&&(r.ok||r.status<500))pendingWrites.delete(fingerprint);
 if(!r.ok)throw Error(v.error?.message||'请求失败');return v.data;
}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
const badge=s=>`<span class="badge">${esc(labels[s]||s)}</span>`,money=n=>'¥'+(Number(n||0)/100).toFixed(2),date=s=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—';
function shell(){const nav=[['/','home','工作台'],['/apps','apps','全部应用'],...[...new Set(apps.map(a=>a.category).filter(Boolean))].map(c=>['/?category='+encodeURIComponent(c),categoryIcon(c),c]),['/me/services','me','我的服务'],['/notifications','notifications','通知消息']];const active=p=>p.startsWith('/?category=')?path==='/'&&location.search===p.slice(1):p==='/'?path==='/'&&!location.search:path.startsWith(p);$('#app').innerHTML=`<div class="demo">演示环境 · 数据不代表真实业务 · 未接入真实系统</div><aside class="sidebar"><a href="/" class="brand"><span class="mark">${ico('library')}</span><span>云栖校园<small>CAMPUS SERVICES</small></span></a><div class="side-menu">${nav.map(([p,i,t])=>`<a class="nav ${active(p)?'active':''}" href="${p}" title="${esc(t)}">${ico(i)}<span>${t}</span></a>`).join('')}</div>${!['STUDENT','TEACHER'].includes(user.activeRole)?`<a class="nav admin-last ${active('/admin')?'active':''}" href="/admin">${ico('admin')}管理工作台</a>`:''}<div class="foot">云栖职业技术学院<br>演示名称 · 校园服务工作台</div></aside><header class="header"><form class="search" id="searchForm">${ico('search')}<input name="q" placeholder="搜索应用、图书、公告与菜品" aria-label="全局搜索"></form><div class="user"><a href="/notifications">${ico('notifications')}</a><span class="avatar">${esc(user.displayName?.slice(-2))}</span><a href="/me">${esc(user.displayName)}</a><div class="account-actions"><select id="role" aria-label="切换角色">${(user.roles||[user.activeRole]).map(r=>`<option value="${esc(r)}" ${r===user.activeRole?'selected':''}>${esc(labels[r]||r)}</option>`).join('')}</select><button class="btn" id="logout">退出</button></div></div></header><main class="main" id="content"><div class="loading">正在加载校园服务…</div></main><nav class="bottom">${[['/','home','首页'],['/apps','apps','服务'],['/notifications','notifications','消息'],['/me','me','我的']].map(([p,i,t])=>`<a href="${p}" class="${active(p)?'active':''}">${ico(i)}${t}</a>`).join('')}</nav>`;$('#searchForm').onsubmit=e=>{e.preventDefault();go('/search?q='+encodeURIComponent(new FormData(e.target).get('q')))};$('#logout').onclick=async()=>{await api('auth/logout','POST',{});user=null;go('/login')};$('#role').onchange=async e=>{await api('auth/role','POST',{role:e.target.value});await boot()}}
function heading(title,sub,action=''){return `<div class="topline"><div><div class="eyebrow">CAMPUS / 校园服务</div><h1 class="title">${title}</h1><p>${sub}</p></div>${action}</div>`}
function serviceCards(items){return `<div class="grid">${items.map((a,i)=>`<div class="card service"><a href="${esc(a.externalUrl&&/^https?:\/\//i.test(a.externalUrl)?a.externalUrl:a.internalPath||a.path||'/apps')}" ${a.externalUrl?'target="_blank" rel="noopener noreferrer"':''} ${['PLANNED','DISABLED','MAINTENANCE'].includes(a.status)?'data-disabled="true"':''} class="row"><div class="iconbox ${i%3===1?'teal':''}">${ico((a.code||a.id)?.toLowerCase()||'apps')}</div><div><h3>${esc(a.name)}</h3><p>${esc(a.description||'便捷校园服务')}</p>${['PLANNED','DISABLED','MAINTENANCE'].includes(a.status)?badge(a.status==='PLANNED'?'规划中':'暂不可用'):''}</div></a><button class="star" data-fav="${esc(a.id)}" aria-label="${a.favorite?'取消收藏':'收藏'}">${a.favorite?'★':'☆'}</button></div>`).join('')}</div>`}
async function login(){const accounts=await api('auth/accounts');$('#app').innerHTML=`<div class="demo">演示环境 · 仅使用虚构身份</div><div class="login"><div class="eyebrow">YUNQI CAMPUS</div><h1>让校园服务，触手可及。</h1><p>云栖职业技术学院 · 演示名称<br>选择演示身份，体验图书、打印与食堂服务。无需真实密码。</p><div class="grid two">${accounts.map(a=>`<button class="card" data-login="${esc(a.id)}"><div class="row"><span class="avatar">${esc(a.displayName?.slice(-2))}</span><div><h3>${esc(a.displayName)}</h3><p>${esc(a.roles.map(r=>labels[r]||r).join(' / '))}</p></div>${ico('arrow')}</div></button>`).join('')}</div><p>学校统一身份与企业微信尚未接入。演示登录仅限 demo 模式。</p></div>`}
async function oldHome(){const h=await api('home');apps=await api('apps');const stats=h.stats||h.counts||h.overview||{};$('#content').innerHTML=heading('你好，'+esc(user.displayName),'在这里，连接你的每一天。')+`<section class="card hero"><div><div class="eyebrow">YOUR CAMPUS, CONNECTED</div><h2>把时间留给热爱<br>让服务更简单</h2><p>图书预约、在线打印、智慧食堂，一站直达。</p><a class="btn primary" href="/apps">探索校园服务 ${ico('arrow')}</a></div><div class="art">CAMPUS<br>2026</div></section><div class="grid stats">${[['待取图书',stats.readyBooks||stats.reservations||0,'library','/library/reservations'],['打印待取',stats.readyPrints||stats.printing||0,'printing','/printing/orders'],['待取餐单',stats.readyMeals||stats.dining||0,'dining','/dining/orders'],['未读消息',stats.unread||stats.unreadNotifications||0,'notifications','/notifications']].map(([t,n,i,p])=>`<a class="card stat" href="${p}"><div><span class="muted">${t}</span><b>${n}</b></div><span class="iconbox">${ico(i)}</span></a>`).join('')}</div><h2 class="section-title">常用服务<a href="/apps">全部应用 →</a></h2>${serviceCards(apps.filter(a=>a.status==='ACTIVE').slice(0,8))}<div class="cols"><section><h2 class="section-title">校园公告</h2><div class="card">${(h.announcements||[]).map(a=>`<div class="listitem"><div><h3>${esc(a.title)}</h3><p>${esc(a.body||a.content)}</p></div><span class="muted">${date(a.createdAt)}</span></div>`).join('')||'<p>暂无已发布公告</p>'}</div></section><section><h2 class="section-title">服务指南</h2><div class="card"><h3>校园生活，有序从容</h3><p>图书预约待馆员确认后取书；打印仅支持 PDF；食堂支持下一开放时段预订。</p><p>全部金额为演示报价，默认到店付款。不会发生真实在线收款。</p><a href="/me/services" class="btn">查看我的服务 ${ico('arrow')}</a></div></section></div>`}
async function appPage(){apps=await api('apps');$('#content').innerHTML=heading(path.includes('favorites')?'我的收藏':'应用中心','校园服务，按需直达。规划中应用暂不可用。')+`<div class="filters">${[...new Set(apps.map(a=>a.category).filter(Boolean))].map(c=>`<button class="btn" data-app-category="${esc(c)}">${esc(c)}</button>`).join('')}<input id="appQuery" aria-label="搜索应用" placeholder="搜索应用名称" class="btn"><button class="btn selected" id="allApps">全部应用</button><button class="btn" id="favApps">只看收藏</button></div><div id="appList">${serviceCards(path.includes('favorites')?apps.filter(a=>a.favorite):apps)}</div>`;$('#appQuery').oninput=e=>$('#appList').innerHTML=serviceCards(apps.filter(a=>a.name.includes(e.target.value)));$('#allApps').onclick=()=>$('#appList').innerHTML=serviceCards(apps);$('#favApps').onclick=()=>$('#appList').innerHTML=serviceCards(apps.filter(a=>a.favorite))}
async function library(){if(/reservations|loans/.test(path))return records(path.includes('loans')?'libraryLoans':'libraryReservations');const books=await api('library/books');$('#content').innerHTML=heading('图书服务','发现一本好书。预约、借阅与归还采用平台演示规则。',`<div class="row"><a class="btn" href="/library/reservations">我的预约</a><a class="btn" href="/library/loans">我的借阅</a></div>`)+`<div class="filters"><input id="bookQuery" class="btn" aria-label="搜索书目" placeholder="搜索书名、作者"></div><div class="grid two" id="books"></div>`;const draw=q=>$('#books').innerHTML=books.filter(b=>(b.title+b.author).includes(q)).map(b=>`<article class="card book"><div class="cover">${esc(b.title)}</div><div><h3><a href="/library/books/${esc(b.id)}">${esc(b.title)}</a></h3><p>${esc(b.author)} · ${esc(b.category)}</p><p>${esc(b.publisher||'校园图书馆')} · ${esc(b.location||'馆藏阅览区')}</p><p>可借 ${b.available??0} 册</p><button class="btn primary" data-reserve="${esc(b.id)}" ${b.available<1?'disabled':''}>预约图书</button></div></article>`).join('')||'<div class="empty">没有匹配的书目</div>';draw('');$('#bookQuery').oninput=e=>draw(e.target.value)}
async function printing(){if(path.includes('orders'))return records('printing');const points=await api('printing/points');$('#content').innerHTML=heading('在线打印','上传 PDF，确认报价后提交。文件仅向本人和对应打印点授权人员开放。',`<a href="/printing/orders" class="btn">我的打印订单</a>`)+`<form id="printForm" class="card form"><h2>新建打印订单</h2><p><a class="btn" href="/api/v1/files/sample">下载演示 PDF 样例</a></p><label class="field">PDF 文件<input type="file" id="pdf" accept="application/pdf" required><small>最大 20MB、300 页。按实际解析页数计价。</small></label><div id="fileInfo" class="muted"></div><label class="field">打印点<select name="pointId">${points.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><div class="grid two"><label class="field">份数<input name="copies" type="number" value="1" min="1" max="20" required></label><label class="field">页码<input name="pages" value="all" placeholder="all 或 1-3,5" required></label><label class="field">颜色<select name="colorMode"><option value="BW">黑白 · ¥0.20 / 印面</option><option value="COLOR">彩色 · ¥1.00 / 印面</option></select></label><label class="field">单双面<select name="duplex"><option value="false">单面</option><option value="true">双面</option></select></label><label class="field">装订<select name="binding"><option value="NONE">不装订</option><option value="STAPLE">订书钉 · ¥1.00 / 份</option></select></label></div><p>演示服务 · 到店支付 · 未发生真实线上收款</p><div id="quote"></div><button class="btn" type="button" id="quoteBtn">计算报价</button> <button class="btn primary" type="submit">确认并提交订单</button><div id="formError" role="alert"></div></form>`;file=null;$('#pdf').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>20*1024*1024)throw Error('文件不得超过20MB');const base64=await new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(r.result.split(',')[1]);r.onerror=no;r.readAsDataURL(f)});file=await api('files','POST',{name:f.name,base64});$('#fileInfo').textContent=`已上传 ${f.name}，解析 ${file.pageCount} 页`}catch(e){file=null;toast(e.message)}};const payload=()=>{if(!file)throw Error('请先上传有效PDF');const d=Object.fromEntries(new FormData($('#printForm')));return {...d,fileId:file.id,copies:Number(d.copies),duplex:d.duplex==='true'}};$('#quoteBtn').onclick=async()=>{try{const q=await api('printing/quotes','POST',payload());$('#quote').innerHTML=`<p>报价：<b>${money(q.amountCents)}</b> · ${q.sheets??q.sheetCount??'—'} 张纸</p>`}catch(e){toast(e.message)}};$('#printForm').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{await api('printing/orders','POST',payload());toast('打印订单已提交');go('/printing/orders')}catch(e){$('#formError').innerHTML=`<p class="error">${esc(e.message)}</p>`;submit.disabled=false}}}
async function dining(){if(path.includes('orders'))return records('dining');const stalls=await api('dining/stalls');selectedStall=stalls.find(s=>path.endsWith(s.id))||stalls[0];cart={};$('#content').innerHTML=heading('智慧食堂','堂食自取 · 单档口下单 · 支持下一开放时段预订',`<a href="/dining/orders" class="btn">我的餐单</a>`)+`<div class="filters">${stalls.map(s=>`<a href="/dining/stalls/${esc(s.id)}" class="btn ${s.id===selectedStall?.id?'selected':''}">${esc(s.name)}</a>`).join('')}</div><div id="menu"></div>`;if(!selectedStall)return;const menu=await api('dining/stalls/'+selectedStall.id+'/menu');$('#menu').innerHTML=`<div class="grid two">${menu.map(p=>`<div class="card"><div class="row"><div class="iconbox teal">${ico('dining')}</div><h3>${esc(p.name)}</h3></div><p>${esc(p.description||'当日新鲜制作，校内档口自取')}</p><div class="row"><b>${money(p.priceCents)}</b><span class="muted">时段库存 ${p.remaining??'按时段'}</span><label>份数 <input type="number" min="0" max="10" value="0" data-product="${esc(p.variantId||p.id)}" style="width:60px;padding:8px;border:1px solid #ddd;border-radius:6px" aria-label="${esc(p.name)}份数"></label></div></div>`).join('')}</div><form id="diningForm" class="card form" style="margin-top:24px"><h3>选择取餐时段</h3><div class="grid two"><label class="field">日期<input name="pickupDate" type="date" value="${new Date(Date.now()+8*3600000).toISOString().slice(0,10)}" required></label><label class="field">时段<select name="pickupSlot"><option value="LUNCH">午餐 11:00—13:30</option><option value="DINNER">晚餐 17:00—19:30</option></select></label></div><p>金额由服务端按在售价格确认，默认到店支付。</p><button class="btn primary">提交餐单</button><p id="diningError" role="alert"></p></form>`;$('#diningForm').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('button');submit.disabled=true;try{const items=[...document.querySelectorAll('[data-product]')].map(el=>({variantId:el.dataset.product,quantity:Number(el.value)})).filter(x=>x.quantity>0);await api('dining/orders','POST',{...Object.fromEntries(new FormData(e.target)),stallId:selectedStall.id,items});toast('餐单已提交');go('/dining/orders')}catch(e){$('#diningError').textContent=e.message;submit.disabled=false}}}
async function records(kind){const config={libraryReservations:['我的图书预约','me/reservations'],libraryLoans:['我的借阅','me/loans'],printing:['我的打印订单','printing/orders'],dining:['我的餐单','dining/orders']}[kind];const rows=await api(config[1]);$('#content').innerHTML=heading(config[0],'业务记录实时保存。所有履约状态以实际操作为准。')+`<div class="card">${rows.length?rows.map(r=>record(r,kind)).join(''):'<div class="empty">暂无记录，前往服务页开启第一笔校园服务。</div>'}</div>`}
function record(r,kind,admin=false){const id=esc(r.id),domain=kind==='libraryReservations'?'library/reservations':kind==='libraryLoans'?'library/loans':kind+'/orders';let actions='';if(!admin){if(['PENDING','READY','SUBMITTED'].includes(r.status)&&kind!=='libraryLoans')actions+=`<button class="btn danger" data-action="${domain}/${id}/cancel">取消</button>`;if(kind==='libraryLoans'&&r.status==='ACTIVE')actions+=`<button class="btn" data-action="library/loans/${id}/renew">续借14天</button>`;if(kind==='printing'&&r.fileId)actions+=`<a class="btn" href="/api/v1/files/${esc(r.fileId)}/download">下载文件</a>`}else{const maps={libraryReservations:{PENDING:['ready','reject'],READY:['fulfill']},libraryLoans:{ACTIVE:['return']},printing:{SUBMITTED:['accept','reject'],ACCEPTED:['start'],PROCESSING:['ready','exception'],READY:['confirm-payment','redeem'],EXCEPTION:['resolve']},dining:{SUBMITTED:['accept','reject'],ACCEPTED:['prepare'],PREPARING:['ready'],READY:['confirm-payment','redeem']}};const titles={ready:'准备待取',reject:'拒绝',fulfill:'办理领取',return:'办理归还',accept:'接单',start:'开始打印',prepare:'开始备餐','confirm-payment':'确认到店收款',redeem:'输入凭证核销',exception:'登记异常',resolve:'恢复前态'};actions+=(maps[kind]?.[r.status]||[]).map(a=>`<button class="btn" data-action="admin/${domain}/${id}/${a}" data-confirm="${a}">${titles[a]}</button>`).join('')}
return `<article class="listitem detail"><div><h3>${esc(r.title||r.bookTitle||r.name||r.fileName||(kind==='printing'?'打印订单':kind==='dining'?'食堂餐单':'图书记录'))} ${badge(r.status)}</h3><p>编号 ${id} · ${date(r.createdAt)} ${r.amountCents!==undefined?' · '+money(r.amountCents):''}</p>${r.dueAt?`<p>应还：${date(r.dueAt)}</p>`:''}${r.paymentStatus?`<p>${esc(labels[r.paymentStatus]||r.paymentStatus)}</p>`:''}${r.pickupToken||r.credential||r.pickupCode?`<p>取件凭证：<strong>${esc(r.pickupToken||r.credential||r.pickupCode)}</strong>（仅供本人使用）</p>`:''}${r.reason?`<p>${esc(r.reason)}</p>`:''}</div><div class="row">${actions}</div></article>`}
async function notifications(){const rows=await api('notifications');$('#content').innerHTML=heading('通知消息','业务进度站内通知。企业微信消息通道尚未接入。',`<button class="btn" data-action="notifications/read-all">全部标为已读</button>`)+`<div class="card">${rows.map(r=>`<article class="listitem notification ${r.readAt?'':'unread'}"><div><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><p>${date(r.createdAt)}</p></div>${!r.readAt?`<button class="btn" data-action="notifications/${esc(r.id)}/read">标为已读</button>`:badge('已读')}</article>`).join('')||'<div class="empty">暂无消息</div>'}</div>`}
async function me(){const links=[...['calendar','tasks','notes','expenses'].map(code=>['/utilities/'+code,'clipboard',utilityNames[code]]),...Object.entries(extensionModules).map(([code,cfg])=>['/extensions/'+code,'clipboard',cfg.name]),...Object.entries(campusModules).map(([code,cfg])=>['/services/'+code,'clipboard',cfg.name]),['/library/reservations','library','我的图书预约'],['/library/loans','library','我的借阅'],['/printing/orders','printing','我的打印'],['/dining/orders','dining','我的餐单'],['/me/favorites','apps','我的收藏'],['/notifications','notifications','通知消息']];$('#content').innerHTML=heading(path.includes('services')?'我的服务':'个人中心','你的校园身份与服务记录。')+`<section class="card"><div class="row"><span class="avatar">${esc(user.displayName?.slice(-2))}</span><div><h2>${esc(user.displayName)}</h2><p>${esc(user.campusId||'虚构演示身份')} · ${esc(labels[user.activeRole]||user.activeRole)}</p></div></div><p>角色仅可在本人已分配的范围内切换。身份与学号由学校管理，无法自行修改。</p></section><h2 class="section-title">服务记录</h2><div class="grid">${links.map(([p,i,t])=>`<a href="${p}" class="card service"><span class="iconbox">${ico(i)}</span><h3>${t}</h3></a>`).join('')}</div><h2 class="section-title">帮助与反馈</h2><div class="card"><p>图书问题请联系图书馆服务台；打印异常由对应打印点人工处理；已备餐餐单请与所属档口协商。当前为本地演示环境，不发送真实通知、不发生真实在线支付。</p></div>`}
async function search(){const q=new URLSearchParams(location.search).get('q')||'';const result=await api('search?q='+encodeURIComponent(q));$('#content').innerHTML=heading('搜索结果','关键词：'+esc(q))+Object.entries(result).map(([group,items])=>Array.isArray(items)?`<h2 class="section-title">${esc({apps:'应用',books:'图书',announcements:'公告',products:'菜品'}[group]||group)}</h2><div class="card">${items.map(i=>`<div class="listitem"><div><h3>${esc(i.name||i.title)}</h3><p>${esc(i.description||i.author||i.body||'')}</p></div></div>`).join('')||'<p>没有匹配结果</p>'}</div>`:'').join('')}
const adminSections=[['','工作概览'],['library/reservations','图书预约'],['library/loans','借还管理'],['printing/orders','打印履约'],['dining/orders','食堂履约'],['users','用户管理'],['jobs','后台任务'],['audit','审计记录'],['integrations','集成状态']];
async function adminLegacy(){const section=path.replace(/^\/admin\/?/,'');$('#content').innerHTML=heading('管理工作台','仅展示当前活动角色可访问的数据和操作。')+`<div class="filters adminlinks">${adminSections.map(([p,t])=>`<a class="btn ${p===section?'selected':''}" href="/admin${p?'/'+p:''}">${t}</a>`).join('')}</div><div id="adminContent" class="card">正在加载…</div>`;try{if(!section){const d=await api('admin');$('#adminContent').innerHTML=`<h2>演示业务概览</h2><div class="grid">${Object.entries(d.stats||d).filter(([,v])=>typeof v==='number').map(([k,v])=>`<div class="card"><span class="muted">${esc({reservations:'今日图书预约',printing:'待处理打印',dining:'待处理餐单',failedJobs:'失败任务'}[k]||k)}</span><h2>${v}</h2></div>`).join('')}</div><p>本地演示统计，仅来自当前数据库。真实接口尚未接入。</p>`;return}const rows=await api('admin/'+section);if(Array.isArray(rows)){let kind=section.startsWith('library/reservations')?'libraryReservations':section.startsWith('library/loans')?'libraryLoans':section.startsWith('printing')?'printing':section.startsWith('dining')?'dining':null;$('#adminContent').innerHTML=(section==='jobs'?'<button class="btn" data-action="admin/jobs/run">运行一次任务</button>':'')+(rows.length?rows.map(r=>kind?record(r,kind,true):`<div class="listitem"><div><h3>${esc(r.displayName||r.name||r.title||r.type||r.action||r.id)} ${r.status?adminBadge(r.status):''}</h3><p>${esc(r.body||r.description||r.resourceType||r.lastError||r.provider||'')} ${r.createdAt?date(r.createdAt):''}</p>${r.roles?`<p>${esc(r.roles.join(' / '))}</p>`:''}</div>${section==='jobs'&&r.status==='FAILED'?`<button class="btn" data-action="admin/jobs/${esc(r.id)}/retry">重试任务</button>`:''}${section==='users'?`<button class="btn" data-toggle-user="${esc(r.id)}" data-status="${esc(r.status)}">${r.status==='DISABLED'?'启用':'停用'}</button>`:''}</div>`).join(''):'<div class="empty">暂无数据，或当前角色没有可管理记录。</div>')}else{$('#adminContent').innerHTML=`<h3>集成与模式</h3><p>${esc(JSON.stringify(rows))}</p>`}}catch(e){$('#adminContent').innerHTML=`<div class="error">${esc(e.message)}</div><p>当前角色可能无此资源权限。请切换本人已分配角色后重试。</p>`}}
async function render(){path=location.pathname;document.body.classList.remove('workbench','sidebar-folded');try{if(path==='/login'||!user){await login();return}shell();if(path==='/')await home();else if(path==='/apps'||path==='/me/favorites')await appPage();else if(/^\/library\/books\//.test(path))await bookDetail();else if(path.startsWith('/library'))await library();else if(path.startsWith('/printing'))await printing();else if(path.startsWith('/dining'))await dining();else if(path.startsWith('/announcements/'))await announcementDetail();else if(path==='/403')$('#content').innerHTML=heading('403 · 无访问权限','当前身份未被授予此服务权限，请切换已分配角色或联系管理员。');else if(path==='/notifications')await notifications();else if(path.startsWith('/me'))await me();else if(path==='/search')await search();else if(path.startsWith('/utilities/')||path.startsWith('/admin/utilities/'))await utilityPage();else if(path.startsWith('/extensions/'))await extensionPage();else if(path.startsWith('/admin/extensions/'))await extensionAdmin();else if(path.startsWith('/services/'))await campusServicePage();else if(path.startsWith('/admin/services/'))await campusServiceAdmin();else if(path.startsWith('/admin'))await admin();else $('#content').innerHTML=heading('404 · 页面不存在','请从左侧导航选择校园服务。')}catch(e){const el=$('#content')||$('#app');el.innerHTML=`<div class="error" role="alert">${esc(e.message)}</div><button class="btn" id="retry">重新加载</button>`;$('#retry').onclick=render}}
async function go(p){history.pushState({},'',p);await render();window.scrollTo(0,0)}
async function boot(){try{user=await api('auth/me');apps=await api('apps')}catch{user=null}await render()}
document.addEventListener('click',async e=>{const a=e.target.closest('a');if(a&&a.origin===location.origin&&!a.pathname.startsWith('/api/')){e.preventDefault();if(a.dataset.use)api('apps/'+a.dataset.use+'/use','POST',{}).catch(()=>{});if(a.dataset.disabled){toast('此应用当前不可用');return}go(a.pathname+a.search);return}const el=e.target.closest('button');if(!el)return;try{if(el.dataset.appCategory){$('#appList').innerHTML=serviceCards(apps.filter(a=>a.category===el.dataset.appCategory));return}if(el.dataset.login){el.disabled=true;user=await api('auth/demo-login','POST',{userId:el.dataset.login});user=await api('auth/me');go('/')}else if(el.dataset.reserve){el.disabled=true;await api('library/reservations','POST',{bookId:el.dataset.reserve});toast('预约已提交，等待馆员确认');await render()}else if(el.dataset.fav){const app=apps.find(a=>a.id===el.dataset.fav);await api('apps/'+el.dataset.fav+'/favorite',app?.favorite?'DELETE':'PUT');app.favorite=!app.favorite;el.textContent=app.favorite?'★':'☆';toast(app.favorite?'已收藏':'已取消收藏')}else if(el.dataset.action){const action=el.dataset.confirm;let body={};if(action==='redeem'){const token=await askText('请输入本人提供的取件凭证');if(!token)return;body={token,code:token}}else if(['reject','exception'].includes(action)){const reason=await askText('请输入原因');if(!reason)return;body={reason}}else if(action==='confirm-payment'&&!await askConfirm('确认已实际收到到店付款？此操作将被审计记录。'))return;else if(el.dataset.action.endsWith('/cancel')&&!await askConfirm('确认取消？'))return;el.disabled=true;await api(el.dataset.action,'POST',body);toast('操作成功');await render()}else if(el.dataset.toggleUser){if(!await askConfirm('确认更改用户状态？'))return;await api('admin/users/'+el.dataset.toggleUser,'POST',{status:el.dataset.status==='DISABLED'?'ACTIVE':'DISABLED'});await render()}}catch(err){toast(err.message)}finally{el.disabled=false}});window.addEventListener('popstate',render);boot();



const resources={
 apps:{title:'应用管理',fields:[['name','应用名称'],['description','简介'],['category','分类'],['internalPath','站内路径'],['externalUrl','外部网址'],['status','状态','DRAFT,ACTIVE,MAINTENANCE,PLANNED,DISABLED']]},
 categories:{title:'应用分类',fields:[['name','分类名称'],['sortOrder','排序','number']]},
 content:{title:'公告内容',fields:[['title','标题'],['body','正文','textarea'],['status','状态','DRAFT,PUBLISHED,ARCHIVED'],['targetRoles','目标角色（逗号分隔，留空为全部）'],['expiresAt','有效期（ISO时间，可空）']]},
 organizations:{title:'组织管理',fields:[['name','组织名称'],['type','组织类型','CAMPUS,DEPARTMENT,CLASS'],['parentId','上级组织编号']]},
 roles:{title:'角色管理',fields:[['name','角色名称'],['permissions','预设权限（逗号分隔）']]},
 'printing/points':{title:'打印点管理',fields:[['name','打印点名称'],['location','位置'],['open','开放','boolean']]},
 'printing/prices':{title:'打印价格规则',fields:[['pointId','打印点编号'],['version','价格版本'],['bwPerSide','黑白每印面（分）','number'],['colorPerSide','彩色每印面（分）','number'],['staplePerCopy','订书钉每份（分）','number']]},
 'dining/stalls':{title:'档口管理',fields:[['name','档口名称'],['hallId','食堂编号'],['open','开放','boolean']]},
 'dining/products':{title:'菜品管理',fields:[['name','菜品名称'],['stallId','档口编号'],['description','菜品说明'],['priceCents','单价（分）','number'],['remaining','初始时段库存','number'],['active','在售','boolean']]},
 settings:{title:'系统设置',fields:[['key','设置项','schoolName,fileRetentionDays'],['value','设置值']]}
};
Object.entries(resources).forEach(([p,c])=>{if(!adminSections.some(([q])=>p===q))adminSections.push([p,c.title])});
function allowedSection(p){const r=user.activeRole;if(r==='SUPER_ADMIN')return !p.startsWith('printing/orders')&&!p.startsWith('dining/orders');if(r==='LIBRARIAN')return p.startsWith('library');if(r==='PRINT_OPERATOR')return p==='printing/orders';if(r==='CANTEEN_MERCHANT')return p.startsWith('dining');if(r==='CAMPUS_OPERATOR')return p.startsWith('utilities/')||p.startsWith('extensions/')||p.startsWith('services/')||['', 'apps','categories','content','banners','jobs','audit','integrations'].includes(p);return false}
function adminHeading(section){return heading('管理工作台','当前角色：'+esc(labels[user.activeRole]||user.activeRole))+`<div class="filters adminlinks">${adminSections.filter(([p])=>allowedSection(p)).map(([p,t])=>`<a class="btn ${p===section?'selected':''}" href="/admin${p?'/'+p:''}">${t}</a>`).join('')}</div>`}
async function adminWithEditor(){let section=path.replace(/^\/admin\/?/,'');if(!section&&!allowedSection('')){const first=adminSections.find(([p])=>allowedSection(p));if(first)return go('/admin/'+first[0])}if(!resources[section]){await adminLegacy();const nav=$('.adminlinks');if(nav)nav.outerHTML=`<div class="filters adminlinks">${adminSections.filter(([p])=>allowedSection(p)).map(([p,t])=>`<a class="btn ${p===section?'selected':''}" href="/admin${p?'/'+p:''}">${t}</a>`).join('')}</div>`;if(section==='users')await enhanceUsers();return}if(!allowedSection(section)){$('#content').innerHTML=adminHeading(section)+'<div class="error">当前角色无此管理权限。</div>';return}
const cfg=resources[section];$('#content').innerHTML=adminHeading(section)+`<div class="card"><div class="topline"><h2>${cfg.title}</h2><button id="newResource" class="btn primary">新增记录</button></div><div class="filters"><input class="btn" id="resourceSearch" placeholder="搜索全部记录" aria-label="搜索管理记录">${serverFilters()}</div><div id="resourceRows">正在加载…</div><div id="resourcePager" class="row"></div></div><div id="resourceEditor" style="margin-top:24px"></div>`;
try{let rows=[],page=1,generation=0;const draw=async()=>{const request=++generation;try{const result=await adminPage(section,page,$('#resourceSearch').value);if(request!==generation)return;rows=Array.isArray(result.data)?result.data:[result.data];let shown=rows,meta=result.meta||{total:rows.length,totalPages:1};$('#resourceRows').innerHTML=shown.map(r=>`<article class="listitem"><div><h3>${esc(r.name||r.title||r.version||r.id||cfg.title)} ${r.status?adminBadge(r.status):''}</h3><p>${esc(r.description||r.body||r.location||r.provider||'')}</p><p class="muted">${esc(r.id||'')} ${r.priceCents!==undefined?money(r.priceCents):''}</p></div><button class="btn" data-edit-resource="${esc(r.id||'settings')}">编辑</button></article>`).join('')||'<div class="empty">没有匹配记录</div>';$('#resourcePager').innerHTML=`<span class="muted">共 ${meta.total} 条 · 第 ${page} / ${Math.max(1,meta.totalPages)} 页</span><button class="btn" id="prevResource" ${page===1?'disabled':''}>上一页</button><button class="btn" id="nextResource" ${page>=meta.totalPages?'disabled':''}>下一页</button>`;$('#prevResource').onclick=()=>{page--;draw()};$('#nextResource').onclick=()=>{page++;draw()};document.querySelectorAll('[data-edit-resource]').forEach(el=>el.onclick=()=>editor(rows.find(r=>(r.id||'settings')===el.dataset.editResource)||{}))}catch(e){$('#resourceRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};
const editor=(record={})=>{$('#resourceEditor').innerHTML=`<form id="resourceForm" class="card form"><h2>${record.id?'编辑':'新增'}${cfg.title}</h2>${cfg.fields.map(([key,label,type])=>`<label class="field">${label}${type==='textarea'?`<textarea name="${key}" rows="5">${esc(record[key]||'')}</textarea>`:type==='boolean'?`<select name="${key}"><option value="true" ${record[key]!==false?'selected':''}>是</option><option value="false" ${record[key]===false?'selected':''}>否</option></select>`:type&&type.includes(',')?`<select name="${key}">${type.split(',').map(v=>`<option value="${v}" ${record[key]===v?'selected':''}>${esc(adminStatusLabel(v)||({DRAFT:'草稿',PUBLISHED:'已发布',ARCHIVED:'归档',PLANNED:'规划中',DISABLED:'禁用',MAINTENANCE:'维护中'}[v])||v)}</option>`).join('')}</select>`:`<input name="${key}" type="${type==='number'?'number':'text'}" ${type==='number'?(key==='quantity'?'min="1" max="5" step="1"':'min="0" step="1"'):''} value="${esc(Array.isArray(record[key])?record[key].join(','):record[key]??'')}">`}</label>`).join('')}<p class="muted">金额以整数分保存。公告正文使用纯文本，不执行 HTML。</p><button class="btn primary">保存</button> <button class="btn" type="button" id="cancelEditor">取消</button><p id="resourceError" role="alert"></p></form>`;$('#cancelEditor').onclick=()=>$('#resourceEditor').innerHTML='';$('#resourceForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button');btn.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));for(const [key,,type]of cfg.fields){if(type==='number'){data[key]=Number(data[key]);if(!Number.isInteger(data[key]))throw Error('数字字段必须是整数')}if(type==='boolean')data[key]=data[key]==='true';if(['permissions','targetRoles'].includes(key))data[key]=data[key].split(',').map(s=>s.trim()).filter(Boolean);if(key==='expiresAt'&&!data[key])data[key]=null}await api('admin/'+section+(record.id?'/'+encodeURIComponent(record.id):''),'POST',data);toast('记录已保存');await admin()}catch(err){$('#resourceError').textContent=err.message}finally{btn.disabled=false}};$('#resourceEditor').scrollIntoView({behavior:'smooth'})};$('#resourceSearch').oninput=()=>{page=1;draw()};$('#newResource').onclick=()=>editor();document.querySelectorAll('[data-server-filter]').forEach(el=>el.onchange=()=>{page=1;draw()});draw()}catch(e){$('#resourceRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function enhanceUsers(){const root=$('#adminContent');if(!root||root.querySelector('.error'))return;let users;try{users=await api('admin/users')}catch{return}const rows=root.querySelectorAll('.listitem');rows.forEach((el,i)=>{const u=users[i];if(!u)return;const b=document.createElement('button');b.className='btn';b.textContent='分配角色与范围';b.onclick=async()=>{const roles=await askText('输入允许的角色（逗号分隔）\n'+Object.keys(labels).filter(x=>/ADMIN|OPERATOR|MERCHANT|STUDENT|TEACHER|LIBRARIAN/.test(x)).join(', '),(u.roles||[]).join(','));if(roles===null)return;const scope=await askText('输入显式业务点范围编号（逗号分隔）',(u.scope||[]).join(','));if(scope===null)return;api('admin/users/'+u.id,'POST',{roles:roles.split(',').map(s=>s.trim()).filter(Boolean),scope:scope.split(',').map(s=>s.trim()).filter(Boolean)}).then(()=>{toast('用户授权已更新');render()}).catch(e=>toast(e.message))};el.append(b)})}


function deskCard(a,i){const planned=a.status!=='ACTIVE',palettes=['blue','teal','orange','purple','green','rose'];return `<a class="desk-app ${planned?'planned':''}" href="${planned?'#':esc(a.internalPath||'/apps')}" ${planned?'data-disabled="true"':`data-use="${esc(a.id)}"`} title="${esc(a.description||a.name)}${planned?' · 规划中，未接入真实系统':''}"><span class="desk-icon ${palettes[i%palettes.length]}">${ico(deskIcon(a))}</span><span class="desk-copy"><b>${esc(a.name)}</b><small>${planned?'规划中 · 未接入':esc(a.description||'本地演示服务')}</small></span>${a.favorite?'<span class="desk-fav">★</span>':''}</a>`}
async function home(){const h=await api('home');apps=(await api('apps')).sort((a,b)=>Number(b.status==='ACTIVE')-Number(a.status==='ACTIVE'));document.body.classList.add('workbench');$('#content').innerHTML=`<div class="workbench-title"><span class="row">${ico('apps')}<b>工作台</b><span class="muted">校园服务 · 企微网页应用演示</span></span><button class="btn" id="foldSide" aria-label="折叠侧栏">折叠侧栏</button></div><div class="desk-toolbar"><div class="desk-tabs" id="deskTabs"></div><form class="desk-search" id="deskSearchForm">${ico('search')}<input id="deskQuery" placeholder="搜索功能、图书、菜品、公告" aria-label="搜索校园全部服务"><button class="btn primary" type="submit">搜索</button></form></div><div class="desk-subbar"><span>全部 <b>${apps.length}</b> 项 · 可体验 <b>${apps.filter(a=>a.status==='ACTIVE').length}</b> 项</span><span>规划目录仅作展示，未接入真实系统</span><select id="deskAvailability" aria-label="应用可用状态"><option value="ALL" selected>全部状态</option><option value="ACTIVE">可用服务</option><option value="PLANNED">待接入</option></select><button class="desk-link" id="deskFavorites">我的收藏</button></div><div class="desk-grid" id="deskGrid"></div><div class="desk-more" id="deskMore"></div><p class="desk-plan-note" id="deskPlanNote">当前优先展示已实现服务。更多规划目录可切换查看。</p><div class="desk-support"><section class="card"><h2>校园公告</h2><div id="deskBanner"></div><div class="row"><button class="btn" id="previousBanner">上一条</button><button class="btn" id="nextBanner">下一条</button></div></section><section class="card"><h2>我的待办 <span class="muted">${h.todos?.length||0} 项</span></h2>${(h.todos||[]).slice(0,4).map(t=>`<a class="listitem" href="${esc(t.targetPath)}"><span>${esc({library:'图书预约',printing:'打印订单',dining:'食堂餐单'}[t.domain]||'校园服务')}</span>${badge(t.status)}</a>`).join('')||'<p>暂无待处理服务</p>'}</section><section class="card"><h2>最近使用</h2>${(h.recentUses||[]).slice(0,5).map(r=>`<a class="listitem" href="${esc(r.app?.internalPath||'/apps')}" data-use="${esc(r.appId)}">${esc(r.app?.name||'校园应用')}<small class="muted">${date(r.usedAt)}</small></a>`).join('')||'<p>打开应用后将在这里记录。</p>'}</section></div>`;
let category=new URLSearchParams(location.search).get('category')||'全部应用',favorites=false,availability='ALL',expanded=false;const categories=['全部应用',...new Set(apps.map(a=>a.category).filter(Boolean))];const draw=()=>{const q=$('#deskQuery').value.trim();$('#deskTabs').innerHTML=categories.map(c=>`<button class="${c===category?'active':''}" data-desk-category="${esc(c)}">${esc(c)}</button>`).join('');const filtered=apps.filter(a=>(category==='全部应用'||a.category===category)&&(!favorites||a.favorite)&&(availability==='ALL'||(availability==='ACTIVE'?a.status==='ACTIVE':a.status!=='ACTIVE'))&&(a.name+(a.description||'')+(a.aliases||[]).join(' ')).includes(q));const limited=!expanded&&category==='全部应用'&&!q&&!favorites&&availability==='ALL'&&filtered.length>80;$('#deskGrid').innerHTML=(limited?filtered.slice(0,80):filtered).map(deskCard).join('')||`<div class="empty desk-empty">${availability==='ACTIVE'?'该分类暂无匹配的可用服务。规划应用尚未接入真实系统。':'没有匹配应用。'}${availability==='ACTIVE'?'<button class="btn" id="showCategoryPlanned">查看该分类规划目录</button>':''}</div>`;$('#deskMore').innerHTML=limited?'<button class="btn" id="expandDirectory">展开全部 '+filtered.length+' 项服务目录</button>':'';if($('#expandDirectory'))$('#expandDirectory').onclick=()=>{expanded=true;draw()};const plannedButton=$('#showCategoryPlanned');if(plannedButton)plannedButton.onclick=()=>{availability='PLANNED';$('#deskAvailability').value='PLANNED';draw()};$('#deskPlanNote').textContent=availability==='ACTIVE'?'当前优先展示已实现服务。更多规划目录可切换查看。':'规划目录仅供查看，未接入的应用不会开放操作。';document.querySelectorAll('[data-desk-category]').forEach(b=>b.onclick=()=>{category=b.dataset.deskCategory;draw()})};$('#deskAvailability').onchange=e=>{availability=e.target.value;draw()};$('#deskQuery').oninput=draw;$('#deskSearchForm').onsubmit=e=>{e.preventDefault();go('/search?q='+encodeURIComponent($('#deskQuery').value.trim()))};$('#deskFavorites').onclick=()=>{favorites=!favorites;$('#deskFavorites').textContent=favorites?'显示全部':'我的收藏';draw()};$('#foldSide').onclick=()=>document.body.classList.toggle('sidebar-folded');draw();let index=0,banners=(h.banners||[]).filter(b=>b.enabled);if(!banners.length)banners=(h.announcements||[]).map(a=>({...a,targetPath:'/announcements/'+a.id}));const banner=()=>{$('#deskBanner').innerHTML=banners.length?`<a href="${esc(banners[index].targetPath||'/notifications')}"><h3>${esc(banners[index].title)}</h3><p>${esc(banners[index].body||'')}</p></a><p class="muted">${index+1} / ${banners.length}</p>`:'<p>暂无公告</p>'};$('#previousBanner').onclick=()=>{index=(index-1+banners.length)%Math.max(1,banners.length);banner()};$('#nextBanner').onclick=()=>{index=(index+1)%Math.max(1,banners.length);banner()};banner()}
async function bookDetail(){const b=await api('library/books/'+path.split('/').pop());$('#content').innerHTML=heading(esc(b.title),'平台演示规则：预约确认后48小时内领取，演示借期30天。',`<a class="btn" href="/library">返回书目</a>`)+`<section class="card"><div class="book"><div class="cover">${esc(b.title)}</div><div><h2>${esc(b.title)}</h2><p>${esc(b.author)} · ${esc(b.publisher)}</p><p>ISBN：${esc(b.isbn)} · ${esc(b.category)}</p><p>馆藏位置：${esc(b.location||b.copies?.[0]?.location||'请查看实体册位置')}</p><p>可借 ${b.available??0} 册</p><button class="btn primary" data-reserve="${esc(b.id)}" ${b.available<1?'disabled':''}>预约图书</button></div></div><h3>实体馆藏</h3>${(b.copies||[]).map(c=>`<div class="listitem"><span>${esc(c.barcode||c.id)} · ${esc(c.location)}</span>${badge(({AVAILABLE:'可借',RESERVED:'已预约',ON_LOAN:'借出',UNAVAILABLE:'不可借'})[c.status]||c.status)}</div>`).join('')||'<p>暂无实体册明细</p>'}</section>`}
async function announcementDetail(){const a=await api('announcements/'+path.split('/').pop());$('#content').innerHTML=heading(esc(a.title),'校园公告 · '+date(a.createdAt))+`<article class="card"><p style="white-space:pre-wrap">${esc(a.body)}</p></article>`}
resources['library/books']={title:'馆藏书目',fields:[['title','书名'],['author','作者'],['publisher','出版社'],['isbn','ISBN'],['category','分类'],['location','馆藏位置'],['copyCount','新书实体册数（1~20）','number']]};resources.banners={title:'轮播公告',fields:[['title','标题'],['body','说明','textarea'],['targetPath','站内跳转路径'],['enabled','启用','boolean'],['sortOrder','排序','number']]};adminSections.push(['library/books','馆藏书目'],['banners','轮播公告']);

resources['dining/inventory']={title:'时段库存',fields:[['variantId','菜品规格编号'],['date','日期（YYYY-MM-DD）'],['slot','时段','LUNCH,DINNER'],['remaining','剩余数量','number']]};adminSections.push(['dining/inventory','时段库存']);

function deskIcon(a){const n=a.name||'';if(/图书|借阅|馆藏/.test(n))return 'library';if(/食|餐|菜/.test(n))return 'dining';if(/打印/.test(n))return 'printing';if(/课表|日历|考勤|预约/.test(n))return 'calendar';if(/学生|人员|组织|社团|人事/.test(n))return 'users';if(/统计|分析|报表|大数据/.test(n))return 'chart';if(/申请|审批|合同|公文|公告|报销|证明|登记/.test(n))return 'document';if(/报修|维修|设备/.test(n))return 'tool';if(/网络|网站|网络|国际/.test(n))return 'globe';if(/教学|课堂|课程|系统/.test(n))return 'monitor';if(/奖|评选|荣誉/.test(n))return 'award';if(/校|楼|场馆|宿舍/.test(n))return 'building';const pool=['apps','clipboard','wallet','folder','mail','message','key','network','heart','bus','flask','briefcase','database','cloud','settings','shield','coffee','graduation'];return pool[[...n].reduce((sum,c)=>sum+c.charCodeAt(0),0)%pool.length]}

function adminStatusLabel(status,section=path.replace(/^\/admin\/?/,'')){if(status==='ACTIVE')return section==='library/loans'?'借阅中':section==='apps'?'已上架':'已启用';return ({DISABLED:'已停用',DRAFT:'草稿',PUBLISHED:'已发布',PLANNED:'规划中',MAINTENANCE:'维护中',ARCHIVED:'已归档',SUCCEEDED:'成功'})[status]||labels[status]||status}
function adminBadge(status){return `<span class="badge">${esc(adminStatusLabel(status))}</span>`}
function serverFilters(){return `<select class="btn" id="serverStatus" data-server-filter aria-label="状态筛选"><option value="">全部状态</option>${['ACTIVE','DISABLED','DRAFT','PUBLISHED','PLANNED','PENDING','SUBMITTED','ACCEPTED','PROCESSING','PREPARING','READY','COMPLETED','CANCELLED','FAILED','SUCCEEDED'].map(v=>`<option value="${v}">${esc(adminStatusLabel(v))}</option>`).join('')}</select><select class="btn" id="serverSort" data-server-filter aria-label="排序字段"><option value="createdAt">创建时间</option><option value="updatedAt">更新时间</option><option value="name">名称</option><option value="title">标题</option><option value="status">状态</option></select><select class="btn" id="serverOrder" data-server-filter aria-label="排序方向"><option value="desc">降序</option><option value="asc">升序</option></select>`}
async function adminPage(section,page,q=''){const params=new URLSearchParams({page:String(page),pageSize:'20',q,status:$('#serverStatus')?.value||'',sort:$('#serverSort')?.value||'createdAt',order:$('#serverOrder')?.value||'desc'});const r=await fetch('/api/v1/admin/'+section+'?'+params,{headers:{'Accept':'application/json'}}),v=await r.json();if(!r.ok)throw Error(v.error?.message||'请求失败');return v}
async function admin(){const section=path.replace(/^\/admin\/?/,'');if(resources[section]||!section)return adminWithEditor();if(!allowedSection(section))return adminWithEditor();$('#content').innerHTML=adminHeading(section)+`<section class="card"><div class="filters"><input class="btn" id="adminQuery" placeholder="搜索全部记录" aria-label="搜索全部记录">${serverFilters()}<button class="btn" id="adminFilter">查询</button></div>${section==='jobs'?'<button class="btn" data-action="admin/jobs/run">运行一次任务</button>':''}<div id="adminRows"></div><div class="row" id="adminPager"></div></section>`;let page=1,generation=0;const draw=async()=>{const request=++generation;try{const {data,meta}=await adminPage(section,page,$('#adminQuery').value);if(request!==generation)return;const rows=Array.isArray(data)?data:[data],m=meta||{total:rows.length,totalPages:1};let kind=section==='library/reservations'?'libraryReservations':section==='library/loans'?'libraryLoans':section==='printing/orders'?'printing':section==='dining/orders'?'dining':null;$('#adminRows').innerHTML=rows.map(r=>kind?record(r,kind,true):`<article class="listitem"><div><h3>${esc(r.displayName||r.name||r.title||r.type||r.action||r.provider||r.id)} ${r.status?adminBadge(r.status):''}</h3><p>${esc(r.body||r.description||r.resourceType||r.lastError||r.message||'')}</p><p class="muted">${esc(r.id||'')} ${r.createdAt?date(r.createdAt):''}</p>${r.roles?`<p>${esc(r.roles.join(' / '))}</p>`:''}</div>${section==='jobs'&&r.status==='FAILED'?`<button class="btn" data-action="admin/jobs/${esc(r.id)}/retry">重试任务</button>`:''}${section==='users'?`<div class="row"><button class="btn" data-toggle-user="${esc(r.id)}" data-status="${esc(r.status)}">${r.status==='DISABLED'?'启用':'停用'}</button><button class="btn" data-authorize="${esc(r.id)}">分配角色与范围</button></div>`:''}</article>`).join('')||'<div class="empty">没有匹配记录</div>';$('#adminPager').innerHTML=`<span class="muted">共 ${m.total} 条 · 第 ${page} / ${Math.max(1,m.totalPages)} 页</span><button class="btn" id="adminPrev" ${page===1?'disabled':''}>上一页</button><button class="btn" id="adminNext" ${page>=m.totalPages?'disabled':''}>下一页</button>`;$('#adminPrev').onclick=()=>{page--;draw()};$('#adminNext').onclick=()=>{page++;draw()};document.querySelectorAll('[data-authorize]').forEach(el=>el.onclick=async()=>{const u=rows.find(r=>r.id===el.dataset.authorize),roles=await askText('输入分配角色（逗号分隔）',u.roles.join(','));if(roles===null)return;const scope=await askText('业务点范围编号（逗号分隔）',(u.scope||[]).join(','));if(scope===null)return;try{await api('admin/users/'+u.id,'POST',{roles:roles.split(',').map(s=>s.trim()).filter(Boolean),scope:scope.split(',').map(s=>s.trim()).filter(Boolean)});toast('用户授权已更新');draw()}catch(e){toast(e.message)}})}catch(e){$('#adminRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};$('#adminFilter').onclick=()=>{page=1;draw()};document.querySelectorAll('[data-server-filter]').forEach(el=>el.onchange=()=>{page=1;draw()});$('#adminQuery').onkeydown=e=>{if(e.key==='Enter'){page=1;draw()}};draw()}

const campusModules={
 repairs:{name:'校园报修',intro:'提交校内设施问题，查看受理与维修进度。',fields:[['title','问题标题'],['location','具体位置'],['description','问题说明','textarea']]},
 venues:{name:'场地预约',intro:'按日期和时段预约演示场地；同一场地同一时段不可重复占用。',fields:[['venueId','预约场地','venues'],['date','预约日期','date'],['slot','预约时段','09:00,10:00,14:00,15:00,19:00'],['purpose','使用用途','textarea']]},
 lost:{name:'失物招领',intro:'发布失物或拾物信息，认领后由发布者确认归还。请勿填写身份证号、完整手机等敏感资料。',fields:[['type','信息类型','LOST,FOUND'],['title','物品名称'],['location','丢失或拾得位置'],['description','特征说明','textarea']]},
 activities:{name:'活动报名',intro:'查看校内演示活动并报名；取消报名会释放名额。',fields:[['eventId','选择活动','events']]},
 feedback:{name:'意见反馈',intro:'提交校园服务建议，查看运营人员的处理回复。',fields:[['category','反馈分类','校园服务,校园生活,平台体验,其他'],['title','反馈标题'],['description','详细说明','textarea']]},
 certificates:{name:'证明申请',intro:'提交证明需求并等待审核。本地演示申请记录不等于学校正式盖章证明。',fields:[['type','证明类型','在读证明,成绩证明,实习证明'],['purpose','申请用途','textarea']]},
 marketplace:{name:'校园二手集市',intro:'发布校内闲置物品信息；仅作信息展示，不提供在线交易或真实收款。',fields:[['title','物品名称'],['category','物品分类','书籍资料,数码设备,生活用品,运动用品,其他'],['priceCents','期望价格（整数分）','number'],['description','物品说明','textarea']]},
 affairs:{name:'办事申请',intro:'统一提交校园办事需求，跟踪审批结果。外部学校业务系统尚未接入。',fields:[['type','事项类型','印章申请,差旅申请,教室借用,行政事项'],['title','事项标题'],['description','申请说明','textarea']]}
};
const serviceLabels={CLOSED:'已关闭',CLAIM_PENDING:'待核实认领',SUBMITTED:'已提交',PENDING:'待审核',APPROVED:'已批准',ACCEPTED:'已受理',PROCESSING:'处理中',IN_PROGRESS:'维修中',RESOLVED:'已解决',COMPLETED:'已完成',REJECTED:'已驳回',CANCELLED:'已取消',OPEN:'发布中',PUBLISHED:'已发布',CLAIMED:'认领处理中',RETURNED:'已归还',SOLD:'已售出',WITHDRAWN:'已撤下',REGISTERED:'已报名',CONFIRMED:'已确认',AVAILABLE:'可预约',ACTIVE:'有效'};
function serviceBadge(s){return `<span class="service-status">${esc(serviceLabels[s]||s)}</span>`}
function serviceName(r,module,options={}){return r.title||r.name||r.type||options.events?.find(e=>e.id===r.eventId)?.title||options.events?.find(e=>e.id===r.eventId)?.name||options.venues?.find(v=>v.id===r.venueId)?.name||campusModules[module].name}
function serviceField([key,label,type],options){const opts=type==='venues'?options.venues:type==='events'?options.events:type==='affairTypes'?options.affairTypes:null;return `<label class="field">${esc(label)}${type==='textarea'?`<textarea name="${key}" rows="4" maxlength="2000" required></textarea>`:opts?`<select name="${key}" required><option value="">请选择</option>${opts.map(o=>`<option value="${esc(typeof o==='string'?o:o.id)}" ${o.enabled===false||o.remaining===0||o.startsAt&&new Date(o.startsAt)<=new Date()?'disabled':''}>${esc(typeof o==='string'?o:o.name||o.title)}${o.enabled===false?' · 已关闭':''}${o.remaining!==undefined?' · 剩余 '+o.remaining+' 名额':''}</option>`).join('')}</select>`:type?.includes(',')?`<select name="${key}">${type.split(',').map(v=>`<option value="${esc(v)}">${esc(({LOST:'寻找失物',FOUND:'拾物招领'})[v]||v)}</option>`).join('')}</select>`:`<input name="${key}" type="${type==='number'?'number':type==='date'?'date':'text'}" ${type==='number'?'min="0" step="1"':type==='date'?`min="${new Date(Date.now()+28800000).toISOString().slice(0,10)}"`:''} maxlength="200" required>`}</label>`}
async function campusServicePage(){const parts=path.split('/').filter(Boolean),module=parts[1],cfg=campusModules[module];if(!cfg){$('#content').innerHTML=heading('404 · 服务不存在','请返回工作台选择服务。');return}const payload=await api('services/'+module),options=payload.options||{},records=payload.records||[],detailId=parts[2];let tab=detailId?'detail':'list';$('#content').innerHTML=heading(cfg.name,cfg.intro,`<a class="btn" href="/">返回工作台</a>`)+`<div class="card service-notice" role="note">${esc(payload.config?.notice||'本地演示业务，不发送真实外部通知')}</div><div class="service-tabs"><button class="btn selected" id="serviceBrowse">${['lost','marketplace'].includes(module)?'信息广场':'我的记录'}</button><button class="btn" style="display:${['lost','marketplace'].includes(module)?'inline-flex':'none'}" id="serviceMine">仅看本人</button><button class="btn primary" id="serviceNew">${module==='activities'?'我要报名':'提交新记录'}</button></div><div id="serviceBody"></div>`;const body=$('#serviceBody');
const draw=(mine=false)=>{tab='list';let rows=records.filter(r=>!mine||r.isOwner||r.userId===user.id);body.innerHTML=(['venues','activities'].includes(module)?`<div class="grid two" style="margin-bottom:20px">${(module==='venues'?options.venues||[]:options.events||[]).map(o=>`<article class="module-option"><h3>${esc(o.name||o.title)}</h3><p>${esc(o.location||o.description||'校内演示资源')} ${o.capacity!==undefined?' · 容量 '+o.capacity:''} ${o.remaining!==undefined?' · 剩余 '+o.remaining:''}</p>${o.startsAt?`<p>${date(o.startsAt)}</p>`:''}</article>`).join('')}</div>`:'')+`<section class="card">${rows.length?rows.map(r=>`<article class="listitem service-record"><div><h3><a href="/services/${module}/${esc(r.id)}">${esc(serviceName(r,module,options))}</a> ${serviceBadge(r.status)}</h3><p>${esc(r.description||r.purpose||r.location||'')}</p><p class="muted">${date(r.createdAt)} ${r.date?' · '+esc(r.date)+' '+esc(r.slot):''} ${r.priceCents!==undefined?' · '+money(r.priceCents):''}</p></div><a class="btn" href="/services/${module}/${esc(r.id)}">查看详情</a></article>`).join(''):'<div class="empty">暂无记录。提交后可在这里查看处理进度。</div>'}</section>`};
const create=()=>{tab='new';body.innerHTML=`<form class="card form" id="serviceForm"><h2>${module==='activities'?'活动报名':'新建'+cfg.name}</h2>${cfg.fields.map(f=>serviceField(module==='affairs'&&f[0]==='type'&&options.affairTypes?.length?[f[0],f[1],'affairTypes']:f,options)).join('')}<p class="muted">本地演示服务 · 数据持久化保存。请勿提交真实个人敏感资料。</p><button class="btn primary" type="submit">确认提交</button><p id="serviceError" role="alert"></p></form>`;$('#serviceForm').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('button');submit.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));if(data.priceCents!==undefined)data.priceCents=Number(data.priceCents);const result=await api('services/'+module,'POST',data);toast('记录已提交');go('/services/'+module+(result.id?'/'+result.id:''))}catch(err){$('#serviceError').className='error';$('#serviceError').textContent=err.message;submit.disabled=false}}};
const detail=async id=>{const r=await api('services/'+module+'/'+id);const owner=r.isOwner||r.userId===user.id;const allowed=r.allowedActions||[];body.innerHTML=`<article class="card service-detail"><div class="topline"><div><h2>${esc(serviceName(r,module,options))}</h2>${serviceBadge(r.status)}</div><a class="btn" href="/services/${module}">返回列表</a></div><p class="muted">记录编号 ${esc(r.id)} · ${date(r.createdAt)}</p>${cfg.fields.map(([key,label])=>r[key]!==undefined?`<h3>${esc(label)}</h3><div class="field-value">${esc(key==='priceCents'?money(r[key]):key==='venueId'?options.venues?.find(v=>v.id===r[key])?.name||r[key]:key==='eventId'?options.events?.find(v=>v.id===r[key])?.name||options.events?.find(v=>v.id===r[key])?.title||r[key]:r[key])}</div>`:'').join('')}${r.referenceNumber?`<h3>演示审核编号</h3><p>${esc(r.referenceNumber)} · 不代表学校正式证明</p>`:''}${r.response||r.reason||r.reply?`<h3>处理回复</h3><div class="field-value">${esc(r.response||r.reason||r.reply)}</div>`:''}${r.history?.length?`<h3>处理记录</h3><div class="service-history">${r.history.map(h=>`<p>${date(h.createdAt||h.at)} · ${esc(serviceLabels[h.status]||h.action||h.status)} ${esc(h.reason||'')}</p>`).join('')}</div>`:''}<div class="row" id="serviceActions" style="margin-top:24px"></div><p id="serviceActionError" role="alert"></p></article>`;
const actions=$('#serviceActions');if(allowed.includes('cancel'))actions.innerHTML+='<button class="btn danger" data-svc-action="cancel">取消申请</button>';if(allowed.includes('close'))actions.innerHTML+='<button class="btn" data-svc-action="close">确认关闭</button>';if(allowed.includes('claim'))actions.innerHTML+='<button class="btn primary" data-svc-action="claim">提交认领说明</button>';if(allowed.includes('sold'))actions.innerHTML+='<button class="btn primary" data-svc-action="sold">标为已售出</button>';if(allowed.includes('withdraw'))actions.innerHTML+='<button class="btn" data-svc-action="withdraw">撤下信息</button>';if(allowed.includes('confirm-return')&&r.claims?.length)actions.innerHTML+=r.claims.filter(c=>c.status==='PENDING').map(c=>`<button class="btn" data-svc-action="confirm-return" data-claim="${esc(c.id)}">确认归还 · ${esc(c.reason||c.id)}</button>`).join('');actions.querySelectorAll('[data-svc-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.svcAction;if(!await askConfirm(b.textContent+'？'))return;let reason='';if(action==='claim'){reason=await askText('请描述物品特征供发布者核实（勿写敏感资料）');if(!reason)return}b.disabled=true;try{await api('services/'+module+'/'+id+'/'+(action==='cancel'?'cancel':'action'),'POST',{action,reason,claimId:b.dataset.claim});toast('操作已保存');await campusServicePage()}catch(e){$('#serviceActionError').className='error';$('#serviceActionError').textContent=e.message;b.disabled=false}})};$('#serviceBrowse').onclick=()=>draw();$('#serviceMine').onclick=()=>draw(true);$('#serviceNew').onclick=create;if(detailId)await detail(detailId);else draw()}
for(const [code,cfg]of Object.entries(campusModules))adminSections.push(['services/'+code,cfg.name]);
async function campusServiceAdmin(){if(path.endsWith('/options'))return serviceOptionsAdmin();const module=path.split('/')[3],cfg=campusModules[module];if(!cfg){$('#content').innerHTML=heading('404 · 服务不存在','请选择已配置服务。');return}let payload=await api('admin/services/'+module),records=payload.records||[],options=payload.options||{};$('#content').innerHTML=adminHeading('services/'+module)+heading(cfg.name+' · 运营处理','按实际处理结果更新状态；所有操作保存审计记录。')+`<div class="card"><div class="filters"><input class="btn" id="svcAdminQuery" placeholder="搜索记录" aria-label="搜索服务记录"><select class="btn" id="svcAdminStatus" aria-label="筛选服务状态"><option value="">全部状态</option>${Object.keys(serviceLabels).map(s=>`<option value="${esc(s)}">${esc(serviceLabels[s]||s)}</option>`).join('')}</select></div><div id="svcAdminRows"></div><div id="svcAdminPager" class="row"></div></div>`;let page=1,generation=0;const draw=async()=>{const request=++generation;const q=$('#svcAdminQuery').value,status=$('#svcAdminStatus').value;try{const result=await api('admin/services/'+module+'?'+new URLSearchParams({page:String(page),pageSize:'20',q,status}));if(request!==generation)return;payload=result;records=payload.records||[];options=payload.options||{};const meta=payload.meta||{total:records.length,totalPages:1};$('#svcAdminRows').innerHTML=records.map(r=>`<article class="listitem service-record"><div><h3>${esc(serviceName(r,module,options))} ${serviceBadge(r.status)}</h3><p>${esc(r.description||r.purpose||r.location||'')}</p><p class="muted">${esc(r.id)} · ${esc(r.userId||'')} · ${date(r.createdAt)} ${r.date?' · '+esc(r.date)+' '+esc(r.slot):''}</p>${r.priceCents!==undefined?`<p>${money(r.priceCents)}</p>`:''}${r.reason||r.reply?`<p>处理回复：${esc(r.response||r.reason||r.reply)}</p>`:''}</div><div class="row">${serviceAdminActions(module,r,payload.config).map(a=>`<button class="btn" data-svc-admin="${esc(r.id)}" data-operation="${esc(typeof a==='string'?a:a.action)}">${esc(typeof a==='string'?serviceActionTitle(a):a.label||serviceActionTitle(a.action))}</button>`).join('')}</div></article>`).join('')||'<div class="empty">没有匹配记录</div>';$('#svcAdminPager').innerHTML=`<span class="muted">共 ${meta.total} 条 · 第 ${page} / ${Math.max(1,meta.totalPages)} 页</span><button class="btn" id="svcPrev" ${page===1?'disabled':''}>上一页</button><button class="btn" id="svcNext" ${page>=meta.totalPages?'disabled':''}>下一页</button>`;$('#svcPrev').onclick=()=>{page--;draw()};$('#svcNext').onclick=()=>{page++;draw()};document.querySelectorAll('[data-svc-admin]').forEach(b=>b.onclick=async()=>{const action=b.dataset.operation,reason=await askText(serviceActionTitle(action)+'：请输入处理说明');if(reason===null)return;if(!reason.trim()){toast('请输入处理说明');return}b.disabled=true;try{let claimId;if(action==='confirm-return'){const detail=await api('admin/services/'+module+'/'+b.dataset.svcAdmin);const claims=(detail.claims||[]).filter(c=>c.status==='PENDING');if(!claims.length)throw Error('暂无待确认认领');const chosenId=await selectClaim(claims);if(!chosenId){b.disabled=false;return}claimId=chosenId}await api('admin/services/'+module+'/'+b.dataset.svcAdmin+'/action','POST',{action,reason,claimId});toast('处理结果已保存');await campusServiceAdmin()}catch(e){toast(e.message);b.disabled=false}})}catch(e){$('#svcAdminRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};$('#svcAdminQuery').oninput=()=>{page=1;draw()};$('#svcAdminStatus').onchange=()=>{page=1;draw()};draw()}
function serviceActionTitle(a){return ({accept:'受理',start:'开始处理',complete:'完成处理',resolve:'回复并解决',approve:'批准',reject:'驳回',close:'关闭',hide:'下架信息',publish:'发布',reply:'回复',cancel:'取消',process:'处理中','confirm-return':'确认归还',withdraw:'撤下信息',sold:'标为已售',review:'审核',confirm:'确认'})[a]||a}
function serviceAdminActions(module,r,config){if(Array.isArray(r.allowedActions))return r.allowedActions;if(config?.actions?.[r.status])return config.actions[r.status];return []}

function selectClaim(claims){return new Promise(resolve=>{const panel=document.createElement('form');panel.className='card form';panel.innerHTML=`<h2>确认失物归还</h2><p>请核实物品特征与认领人，选择实际归还对象。</p><label class="field">认领申请<select required name="claimId"><option value="">请选择认领人</option>${claims.map(c=>`<option value="${esc(c.id)}">${esc(c.claimantName||'校园用户')}：${esc(c.reason)}</option>`).join('')}</select></label><button class="btn primary">确认归还给此人</button> <button class="btn" type="button">取消</button>`;$('#svcAdminRows').prepend(panel);panel.scrollIntoView({behavior:'smooth'});panel.onsubmit=e=>{e.preventDefault();const id=new FormData(panel).get('claimId');panel.remove();resolve(id)};panel.querySelector('[type=button]').onclick=()=>{panel.remove();resolve(null)}})}
adminSections.push(['services/venues/options','场地配置'],['services/activities/options','活动配置']);
async function serviceOptionsAdmin(){const module=path.split('/')[3],activity=module==='activities',title=activity?'活动资源配置':'场地资源配置',payload=await api('admin/services/'+module+'/options'),rows=payload.records||[];$('#content').innerHTML=adminHeading('services/'+module+'/options')+heading(title,'配置本地演示资源。修改容量与活动时间受已报名记录约束。')+`<section class="card"><button class="btn primary" id="newServiceOption">新增${activity?'活动':'场地'}</button><div id="optionRows">${rows.map(r=>`<article class="listitem"><div><h3>${esc(r.name)} ${r.enabled===false?badge('已停用'):badge('已启用')}</h3><p>${esc(r.location)} · 容量 ${r.capacity}${r.remaining!==undefined?' · 剩余 '+r.remaining:''}</p>${r.startsAt?`<p>${date(r.startsAt)}</p>`:''}<p class="muted">${esc(r.id)}</p></div><button class="btn" data-option-edit="${esc(r.id)}">编辑</button></article>`).join('')||'<div class="empty">暂无配置资源</div>'}</div></section><div id="optionEditor" style="margin-top:20px"></div>`;const edit=(record={})=>{$('#optionEditor').innerHTML=`<form class="card form" id="optionForm"><h2>${record.id?'编辑':'新增'}${activity?'活动':'场地'}</h2><label class="field">名称<input name="name" value="${esc(record.name||'')}" required maxlength="100"></label><label class="field">位置<input name="location" value="${esc(record.location||'')}" required maxlength="200"></label><label class="field">容量<input name="capacity" type="number" min="1" max="10000" step="1" value="${record.capacity||20}" required></label><label class="field">是否开放<select name="enabled"><option value="true" ${record.enabled!==false?'selected':''}>开放</option><option value="false" ${record.enabled===false?'selected':''}>关闭</option></select></label>${activity?`<label class="field">开始时间（北京时间）<input name="startsAt" type="datetime-local" value="${record.startsAt?new Date(new Date(record.startsAt).getTime()+28800000).toISOString().slice(0,16):''}" required></label><label class="field">活动说明<textarea name="description" rows="4" required>${esc(record.description||'')}</textarea></label>`:''}<p class="muted">容量不能低于已有报名数；已有报名的活动不能更改开始时间。</p><button class="btn primary">保存配置</button><p id="optionError" role="alert"></p></form>`;$('#optionForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.capacity=Number(data.capacity);data.enabled=data.enabled==='true';if(record.id)data.id=record.id;if(activity){const original=record.startsAt?new Date(new Date(record.startsAt).getTime()+28800000).toISOString().slice(0,16):null;data.startsAt=original===data.startsAt?record.startsAt:new Date(data.startsAt+':00+08:00').toISOString()}await api('admin/services/'+module+'/options','POST',data);toast('资源配置已保存');serviceOptionsAdmin()}catch(err){$('#optionError').className='error';$('#optionError').textContent=err.message;b.disabled=false}};$('#optionEditor').scrollIntoView({behavior:'smooth'})};$('#newServiceOption').onclick=()=>edit();document.querySelectorAll('[data-option-edit]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.optionEdit)))}

function askText(message,value=''){return campusDialog({message,value,input:true})}
function askConfirm(message){return campusDialog({message,input:false})}
function campusDialog({message,value='',input=false}){return new Promise(resolve=>{const dialog=document.createElement('dialog');dialog.className='campus-dialog';dialog.innerHTML=`<form><h2>${input?'填写信息':'请确认操作'}</h2><p class="dialog-message">${esc(message)}</p>${input?`<label class="field">内容<textarea name="value" rows="4" maxlength="2000" autofocus>${esc(value)}</textarea></label>`:''}<div class="row"><button class="btn primary" type="submit">确认</button><button class="btn" type="button" data-dialog-cancel>取消</button></div></form>`;document.body.append(dialog);let settled=false;const finish=result=>{if(settled)return;settled=true;dialog.close();dialog.remove();resolve(result)};dialog.querySelector('form').onsubmit=e=>{e.preventDefault();finish(input?new FormData(e.target).get('value'):true)};dialog.querySelector('[data-dialog-cancel]').onclick=()=>finish(input?null:false);dialog.addEventListener('cancel',e=>{e.preventDefault();finish(input?null:false)});dialog.showModal();if(input)dialog.querySelector('textarea').focus();else dialog.querySelector('button').focus()})}



function categoryIcon(c){return /图书/.test(c)?'library':/后勤|生活/.test(c)?'coffee':/教务|教学/.test(c)?'graduation':/行政/.test(c)?'briefcase':/学工|学生/.test(c)?'users':/场馆|运动/.test(c)?'building':/活动/.test(c)?'calendar':/就业/.test(c)?'briefcase':/科研/.test(c)?'flask':/交易/.test(c)?'wallet':/反馈|交流/.test(c)?'message':/数字|网络/.test(c)?'network':'apps'}
const extensionModules={housing:{name:'住宿服务',intro:'本地演示床位分配与退宿记录，不代表学校正式住宿安排。',fields:[['reason','住宿申请说明','textarea']]},leaves:{name:'学生请假',intro:'本地人工请假审批与返校销假，不发送真实教务或辅导员通知。',fields:[['startDate','开始日期','date'],['endDate','结束日期','date'],['reason','请假原因','textarea']]},parcels:{name:'校园包裹',intro:'演示包裹入库与本人凭证领取；不连接快递公司物流系统。',fields:[]},equipment:{name:'设备借用',intro:'申请演示设备，审批出借后由运营人员办理归还。',fields:[['deviceId','设备','devices'],['quantity','借用数量（1~5）','number'],['purpose','借用用途','textarea']]},jobs:{name:'校园招聘',intro:'本地演示岗位发布与投递处理，不向外部企业发送简历。',fields:[['jobId','选择岗位','jobs'],['motivation','申请说明','textarea']]},surveys:{name:'校园问卷',intro:'本地演示问卷，每人限答一次。运营人员仅查看匿名汇总。',fields:[['surveyId','选择问卷','surveys']]}};
const extensionActionTitles={allocate:'分配床位',checkout:'办理退宿',approve:'批准',reject:'驳回',return:'归还 / 销假',issue:'办理出借',withdraw:'撤回投递',review:'进入审核',interview:'邀请面试',accept:'录用',redeem:'凭证领取',cancel:'取消申请'};
Object.assign(serviceLabels,{ALLOCATED:'已分配',CHECKED_OUT:'已退宿',ON_LOAN:'借用中',PENDING_PICKUP:'待领取',PICKED_UP:'已领取',SUBMITTED:'已提交',INTERVIEW:'待面试',REVIEWING:'审核中',HIRED:'已录用',ACCEPTED:'已受理',ANSWERED:'已提交问卷'});
for(const [m,c]of Object.entries(extensionModules)){adminSections.push(['extensions/'+m,c.name]);if(!['leaves','parcels'].includes(m))adminSections.push(['extensions/'+m+'/options',c.name+'配置'])}
function extensionName(r,m,options){return r.title||r.name||r.jobTitle||r.deviceName||r.surveyTitle||r.trackingNumber||options.jobs?.find(x=>x.id===r.jobId)?.title||options.devices?.find(x=>x.id===r.deviceId)?.name||extensionModules[m].name}
function extensionFormField([key,label,type],options,record={}){const choices=options[type];if(Array.isArray(choices))return `<label class="field">${esc(label)}<select name="${key}" required><option value="">请选择</option>${choices.map(o=>`<option value="${esc(o.id)}" ${record[key]===o.id?'selected':''} ${o.enabled===false||type==='devices'&&o.remaining<1?'disabled':''}>${esc(o.name||o.title||o.id)}${o.available!==undefined?' · 可用 '+o.available:o.remaining!==undefined?' · 剩余 '+o.remaining:''}</option>`).join('')}</select></label>`;return `<label class="field">${esc(label)}${type==='textarea'?`<textarea name="${key}" rows="4" required maxlength="2000">${esc(record[key]||'')}</textarea>`:`<input name="${key}" type="${type==='number'?'number':type==='date'?'date':type==='datetime-local'?'datetime-local':'text'}" value="${esc(record[key]??'')}" ${type==='number'?'min="0" step="1"':''} ${key==='endsAt'?'':'required'} maxlength="200">`}</label>`}
async function extensionPage(){const [,m,id]=path.split('/').filter(Boolean),cfg=extensionModules[m];if(!cfg){$('#content').innerHTML=heading('404 · 服务不存在','请返回工作台。');return}const page=Number(new URLSearchParams(location.search).get('page')||1);const payload=await api('extensions/'+m+'?page='+page+'&pageSize=20'),options=payload.options||{},records=payload.records||[];$('#content').innerHTML=heading(cfg.name,cfg.intro,`<a class="btn" href="/">返回工作台</a>`)+`<div class="card service-notice">${esc(payload.config?.notice||cfg.intro)}</div><div class="service-tabs"><a class="btn" href="/extensions/${m}">我的记录</a>${m!=='parcels'?'<button class="btn primary" id="extensionNew">'+(m==='surveys'?'填写问卷':'提交申请')+'</button>':''}</div><div id="extensionBody"></div>`;
const draw=()=>{$('#extensionBody').innerHTML=(['jobs','equipment','surveys'].includes(m)?`<div class="grid two" style="margin-bottom:20px">${(options[m==='equipment'?'devices':m]||[]).map(o=>`<article class="module-option"><h3>${esc(o.name||o.title)}</h3><p>${esc(o.description||o.location||'本地演示资源')}</p>${o.available!==undefined?`<p>可借 ${o.available}</p>`:''}</article>`).join('')}</div>`:'')+`<section class="card">${records.map(r=>`<article class="listitem"><div><h3>${esc(extensionName(r,m,options))} ${extensionStatus(r.status,m)}</h3><p>${esc(r.reason||r.purpose||r.response||'')}</p><p class="muted">${date(r.createdAt)}</p></div><a class="btn" href="/extensions/${m}/${esc(r.id)}">查看详情</a></article>`).join('')||'<div class="empty">暂无记录。</div>'}</section>`};
const create=()=>{$('#extensionBody').innerHTML=`<form class="card form" id="extensionForm"><h2>${cfg.name}</h2>${cfg.fields.map(f=>extensionFormField(f,options)).join('')}<div id="surveyQuestions"></div><button class="btn primary">确认提交</button><p id="extensionError" role="alert"></p></form>`;if(m==='surveys'){const select=$('#extensionForm select');const questions=()=>{const survey=options.surveys?.find(s=>s.id===select.value);$('#surveyQuestions').innerHTML=(survey?.questions||[]).map((q,i)=>`<label class="field">${esc(q.title||q.text||q.label||'问题 '+(i+1))}<select name="answer:${esc(q.id||'q'+(i+1))}" required><option value="">请选择</option>${(q.options||[]).map(v=>`<option value="${esc(typeof v==='string'?v:v.value||v.label)}">${esc(typeof v==='string'?v:v.label||v.value)}</option>`).join('')}</select></label>`).join('')};select.onchange=questions;questions()}$('#extensionForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{let data=Object.fromEntries(new FormData(e.target));if(data.quantity!==undefined)data.quantity=Number(data.quantity);if(m==='surveys'){const answers={};for(const [k,v]of Object.entries(data))if(k.startsWith('answer:')){answers[k.slice(7)]=v;delete data[k]}data.answers=answers}const r=await api('extensions/'+m,'POST',data);toast('提交已保存');go('/extensions/'+m+(r.id?'/'+r.id:''))}catch(err){$('#extensionError').className='error';$('#extensionError').textContent=err.message;b.disabled=false}}};
if($('#extensionNew'))$('#extensionNew').onclick=create;if(id){const r=await api('extensions/'+m+'/'+id);$('#extensionBody').innerHTML=`<section class="card"><h2>${esc(extensionName(r,m,options))} ${extensionStatus(r.status,m)}</h2><p class="muted">${esc(r.id)} · ${date(r.createdAt)}</p>${extensionDetailFields(r)}${r.pickupToken?`<h3>本人领取凭证</h3><p style="font-size:18px;word-break:break-all">${esc(r.pickupToken)}</p><p class="muted">请仅向校园包裹服务台出示，领取后失效。</p>`:''}<div class="row" id="extensionActions"></div></section>`;$('#extensionActions').innerHTML=(r.allowedActions||[]).map(a=>`<button class="btn" data-extension-action="${esc(a)}">${esc(extensionActionLabel(a,m))}</button>`).join('');document.querySelectorAll('[data-extension-action]').forEach(b=>b.onclick=async()=>{if(!await askConfirm('确认'+b.textContent+'？'))return;b.disabled=true;try{await api('extensions/'+m+'/'+id+'/action','POST',{action:b.dataset.extensionAction});toast('操作已保存');extensionPage()}catch(e){toast(e.message);b.disabled=false}})}else{draw();const meta=payload.meta;if(meta&&meta.totalPages>1)$('#extensionBody').innerHTML+=`<div class="row" style="margin-top:16px"><span class="muted">共 ${meta.total} 条 · 第 ${page} / ${meta.totalPages} 页</span>${page>1?`<a class="btn" href="/extensions/${m}?page=${page-1}">上一页</a>`:''}${page<meta.totalPages?`<a class="btn" href="/extensions/${m}?page=${page+1}">下一页</a>`:''}</div>`}}
function extensionDetailFields(r){const labels={reason:'申请说明',purpose:'用途',startDate:'开始日期',endDate:'结束日期',response:'处理回复',motivation:'投递说明',quantity:'数量',bedName:'分配床位',bedId:'床位编号',carrier:'承运商',trackingNumber:'运单号',returnedAt:'归还时间',startsAt:'开始时间',endsAt:'结束时间',answers:'问卷答案'};return Object.entries(labels).filter(([k])=>r[k]!==undefined).map(([k,n])=>`<h3>${n}</h3><p style="white-space:pre-wrap">${esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])}</p>`).join('')}
const extensionResourceFields={housing:[['building','宿舍楼'],['room','房间'],['label','床位号']],equipment:[['name','设备名称'],['description','设备说明','textarea'],['total','设备总量','number']],jobs:[['title','岗位名称'],['employer','招聘单位'],['description','岗位说明','textarea'],['deadline','截止时间（北京时间）','datetime-local']],surveys:[['title','问卷标题'],['endsAt','截止时间（北京时间）','datetime-local']]};
Object.assign(serviceLabels,{REQUESTED:'待出借',REVIEWED:'审核完成',COLLECTED:'已领取'});
async function extensionAdmin(){const m=path.split('/')[3],cfg=extensionModules[m];if(!cfg){$('#content').innerHTML=heading('404','服务不存在');return}if(path.endsWith('/options'))return extensionOptionsAdmin(m);$('#content').innerHTML=adminHeading('extensions/'+m)+heading(cfg.name+' · 运营工作台',cfg.intro)+`<div class="card service-notice">本地演示业务，所有处理结果不代表学校正式决定。</div>${m==='parcels'?'<button class="btn primary" id="parcelInbound">包裹入库</button><div id="parcelForm"></div>':''}<section class="card"><div class="filters"><input class="btn" id="extQuery" placeholder="搜索全部记录" aria-label="搜索全部记录"><select class="btn" id="extStatus"><option value="">全部状态</option>${Object.keys(serviceLabels).map(s=>`<option value="${s}">${esc(serviceLabels[s])}</option>`).join('')}</select><button class="btn" id="extSearch">查询</button></div><div id="extAdminRows"></div><div class="row" id="extPager"></div></section>`;let page=1,generation=0;const draw=async()=>{const request=++generation;try{const payload=await api('admin/extensions/'+m+'?'+new URLSearchParams({page:String(page),pageSize:'20',q:$('#extQuery').value,status:$('#extStatus').value}));if(request!==generation)return;const rows=payload.records||[],options=payload.options||{},meta=payload.meta||{total:rows.length,totalPages:1};$('#extAdminRows').innerHTML=rows.map(r=>m==='surveys'?`<section class="module-option"><h3>${esc(r.title)} · 共 ${r.total} 份匿名答卷</h3>${(r.questions||[]).map(q=>`<h4>${esc(q.title)}</h4>${Object.entries(q.counts||{}).map(([name,count])=>`<div class="listitem"><span>${esc(name)}</span><strong>${count}</strong></div>`).join('')}`).join('')}</section>`:`<article class="listitem"><div><h3>${esc(extensionName(r,m,options))} ${extensionStatus(r.status,m)}</h3><p class="muted">${esc(r.id)} · ${esc(r.userId)} · ${date(r.createdAt)}</p>${extensionDetailFields(r)}</div><div class="row">${(r.allowedActions||[]).map(a=>`<button class="btn" data-ext-admin="${esc(r.id)}" data-ext-action="${esc(a)}">${esc(extensionActionTitles[a]||a)}</button>`).join('')}</div></article>`).join('')||'<div class="empty">暂无匹配记录</div>';$('#extPager').innerHTML=`<span class="muted">共 ${meta.total} 条 · 第 ${page} / ${Math.max(1,meta.totalPages)} 页</span><button class="btn" id="extPrev" ${page===1?'disabled':''}>上一页</button><button class="btn" id="extNext" ${page>=meta.totalPages?'disabled':''}>下一页</button>`;$('#extPrev').onclick=()=>{page--;draw()};$('#extNext').onclick=()=>{page++;draw()};document.querySelectorAll('[data-ext-admin]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const action=b.dataset.extAction,data={action};if(action==='redeem'){const token=await askText('请由收件人提供本人领取凭证');if(!token)return;data.token=token}else{const reason=await askText(extensionActionLabel(action,m)+'：请输入处理说明');if(!reason?.trim())return;data.reason=reason}if(action==='allocate'){const beds=(options.beds||[]).filter(x=>x.enabled&&x.available);if(!beds.length)throw Error('暂无可分配床位，请先配置资源');data.bedId=await selectOption('选择实际分配床位',beds.map(x=>({value:x.id,label:x.name})));if(!data.bedId)return}await api('admin/extensions/'+m+'/'+b.dataset.extAdmin+'/action','POST',data);toast('处理已保存');draw()}catch(e){toast(e.message)}finally{b.disabled=false}});if(m==='parcels')$('#parcelInbound').onclick=()=>parcelInbound(options,draw)}catch(e){$('#extAdminRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};$('#extSearch').onclick=()=>{page=1;draw()};$('#extStatus').onchange=()=>{page=1;draw()};$('#extQuery').onkeydown=e=>{if(e.key==='Enter'){page=1;draw()}};draw()}
function selectOption(title,items){return new Promise(resolve=>{const d=document.createElement('dialog');d.className='campus-dialog';d.innerHTML=`<form><h2>${esc(title)}</h2><label class="field">请选择<select name="value" required><option value="">请选择</option>${items.map(x=>`<option value="${esc(x.value)}">${esc(x.label)}</option>`).join('')}</select></label><div class="row"><button class="btn primary">确认</button><button class="btn" type="button">取消</button></div></form>`;document.body.append(d);let done=false;const finish=v=>{if(done)return;done=true;d.close();d.remove();resolve(v)};d.querySelector('form').onsubmit=e=>{e.preventDefault();finish(new FormData(e.target).get('value'))};d.querySelector('[type=button]').onclick=()=>finish(null);d.oncancel=e=>{e.preventDefault();finish(null)};d.showModal()})}
function parcelInbound(options,refresh){$('#parcelForm').innerHTML=`<form class="card form" id="parcelInboundForm" style="margin:16px 0"><h2>包裹入库</h2><label class="field">收件人<select name="recipientId" required><option value="">请选择演示收件人</option>${(options.recipients||[]).map(x=>`<option value="${esc(x.id)}">${esc(x.displayName)} · ${esc(x.campusId)}</option>`).join('')}</select></label><label class="field">运单号<input name="trackingNumber" required maxlength="100"></label><label class="field">承运商<input name="carrier" required maxlength="100"></label><button class="btn primary">确认入库</button><p id="parcelError" role="alert"></p></form>`;$('#parcelInboundForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('admin/extensions/parcels','POST',Object.fromEntries(new FormData(e.target)));toast('包裹已入库，收件人可查看领取凭证');$('#parcelForm').innerHTML='';refresh()}catch(err){$('#parcelError').className='error';$('#parcelError').textContent=err.message;b.disabled=false}}}
async function extensionOptionsAdmin(m){const cfg=extensionModules[m],payload=await api('admin/extensions/'+m+'/options'),rows=payload.records||[];$('#content').innerHTML=adminHeading('extensions/'+m+'/options')+heading(cfg.name+'资源管理','本地演示资源配置，保存后直接用于学生服务。')+`<section class="card"><button class="btn primary" id="extensionResourceNew">新增资源</button>${rows.map(r=>`<article class="listitem"><div><h3>${esc(r.title||r.name)} ${badge(r.enabled?'已启用':'已停用')}</h3><p>${esc(r.description||r.employer||r.room||'')}</p><p class="muted">${esc(r.id)}</p></div><button class="btn" data-ext-resource="${esc(r.id)}">编辑</button></article>`).join('')}</section><div id="extensionResourceEditor" style="margin-top:20px"></div>`;
const edit=(record={})=>{const fields=extensionResourceFields[m],prepared={...record};for(const [key,,type]of fields)if(type==='datetime-local'&&record[key])prepared[key]=new Date(new Date(record[key]).getTime()+28800000).toISOString().slice(0,16);$('#extensionResourceEditor').innerHTML=`<form class="card form" id="extensionResourceForm"><h2>${record.id?'编辑':'新增'}资源</h2>${fields.map(f=>extensionFormField(f,{},prepared)).join('')}<label class="field">启用<select name="enabled"><option value="true" ${record.enabled!==false?'selected':''}>启用</option><option value="false" ${record.enabled===false?'selected':''}>停用</option></select></label>${m==='surveys'?`<div id="surveyResourceQuestions"></div><button class="btn" type="button" id="surveyAddQuestion">增加问题</button><p class="muted">每题2~8个选项；已有答卷后不可修改题目。</p>`:''}<button class="btn primary">保存资源</button><p id="extensionResourceError" role="alert"></p></form>`;if(m==='surveys'){let qs=record.questions||[{id:'q1',title:'',options:['','']}];const questions=()=>{$('#surveyResourceQuestions').innerHTML=qs.map((q,i)=>`<div class="module-option"><label class="field">问题 ${i+1}<input name="questionTitle:${i}" value="${esc(q.title)}" required></label><label class="field">选项（每行一项）<textarea name="questionChoices:${i}" rows="4" required>${esc(q.options.join('\n'))}</textarea></label></div>`).join('')};$('#surveyAddQuestion').onclick=()=>{document.querySelectorAll('[name^="questionTitle:"]').forEach((el,i)=>{qs[i].title=el.value;qs[i].options=$(`[name="questionChoices:${i}"]`).value.split('\n')});qs.push({id:'q'+(qs.length+1),title:'',options:['','']});questions()};questions();$('#extensionResourceForm')._questions=qs}$('#extensionResourceForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit],button:not([type])');b.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));data.enabled=data.enabled==='true';if(record.id){data.id=record.id;data.version=record.version}for(const [key,,type]of fields){if(type==='number')data[key]=Number(data[key]);if(type==='datetime-local')data[key]=data[key]?prepared[key]===data[key]?record[key]:new Date(data[key]+':00+08:00').toISOString():null}if(m==='surveys'){data.questions=e.target._questions.map((q,i)=>({id:q.id,title:data['questionTitle:'+i],options:data['questionChoices:'+i].split('\n').map(x=>x.trim()).filter(Boolean)}));for(const k of Object.keys(data))if(k.startsWith('questionTitle:')||k.startsWith('questionChoices:'))delete data[k]}await api('admin/extensions/'+m+'/options','POST',data);toast('资源保存成功');extensionOptionsAdmin(m)}catch(err){$('#extensionResourceError').className='error';$('#extensionResourceError').textContent=err.message;b.disabled=false}};$('#extensionResourceEditor').scrollIntoView({behavior:'smooth'})};$('#extensionResourceNew').onclick=()=>edit();document.querySelectorAll('[data-ext-resource]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.extResource)))}
const utilityNames={calendar:'个人日程',tasks:'待办清单',notes:'个人笔记',expenses:'个人记账',contacts:'校园通讯录',places:'校园地点查询',shuttles:'校车时刻',hours:'开放时间',guides:'办事指南',resources:'资料下载',faq:'常见问题',schoolcalendar:'校园校历'};
for(const code of ['contacts','places','shuttles','hours','guides','resources','faq','schoolcalendar'])adminSections.push(['utilities/'+code,utilityNames[code]]);
async function utilityPage(){const admin=path.startsWith('/admin/'),parts=path.split('/').filter(Boolean),m=parts[admin?2:1],base=(admin?'admin/':'')+'utilities/'+m;let page=1,generation=0;const first=await api(base+'?page=1&pageSize=20'),cfg=first.config;if(!cfg)throw Error('服务配置不可用');$('#content').innerHTML=(admin?adminHeading('utilities/'+m):'')+heading(esc(cfg.name),cfg.private?'个人数据仅本人可见，刷新后仍会保留。':'校内演示信息查询。')+`<div class="card service-notice">${esc(cfg.notice||'本地演示服务，不代表学校真实运营信息。')}</div><section class="card"><div class="service-toolbar"><div class="row"><input class="btn" id="utilityQuery" placeholder="搜索全部记录" aria-label="搜索全部记录"><button class="btn" id="utilitySearch">搜索</button></div>${cfg.canCreate?'<button class="btn primary" id="utilityNew">新增记录</button>':''}</div><div id="utilitySummary"></div><div id="utilityRows"></div><div class="row" id="utilityPager"></div></section><div id="utilityEditor" style="margin-top:20px"></div>`;
const displayValue=(f,v)=>f.type==='datetime-local'?date(v):f.key==='amountCents'?money(v):String(v??'');
const edit=(record={})=>{const prepared={...record};for(const f of cfg.fields)if(f.type==='datetime-local'&&record[f.key])prepared[f.key]=new Date(new Date(record[f.key]).getTime()+28800000).toISOString().slice(0,16);$('#utilityEditor').innerHTML=`<form class="card form" id="utilityForm"><h2>${record.id?'编辑记录':'新增记录'}</h2>${cfg.fields.map(f=>`<label class="field">${esc(f.label)}${f.type==='datetime-local'?'（北京时间）':''}${f.type==='textarea'?`<textarea name="${esc(f.key)}" rows="5" maxlength="8000" ${f.required?'required':''}>${esc(prepared[f.key]||'')}</textarea>`:`<input name="${esc(f.key)}" type="${esc(f.type||'text')}" value="${esc(prepared[f.key]??'')}" ${f.type==='number'?'min="0" step="1"':''} ${f.required?'required':''}>`}</label>`).join('')}<p class="muted">${esc(cfg.notice||'本地演示记录')}</p><button class="btn primary">保存</button> <button class="btn" type="button" id="utilityCancel">取消</button><p id="utilityError" role="alert"></p></form>`;$('#utilityCancel').onclick=()=>$('#utilityEditor').innerHTML='';$('#utilityForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(e.target));for(const f of cfg.fields){if(f.type==='number')data[f.key]=Number(data[f.key]);if(f.type==='datetime-local')data[f.key]=prepared[f.key]===data[f.key]?record[f.key]:new Date(data[f.key]+':00+08:00').toISOString()}if(record.id)data.version=record.version;await api(base+(record.id?'/'+record.id:''),'POST',data);toast('记录已保存');$('#utilityEditor').innerHTML='';draw()}catch(err){$('#utilityError').className='error';$('#utilityError').textContent=err.message;button.disabled=false}};$('#utilityEditor').scrollIntoView({behavior:'smooth'})};
const actionTitles={edit:'编辑',archive:'归档',complete:'完成待办',reopen:'重新打开',pin:'置顶',unpin:'取消置顶',publish:'发布',unpublish:'撤下',export:'下载资料'};
const draw=async(initial)=>{const request=++generation;try{const payload=initial||await api(base+'?'+new URLSearchParams({page:String(page),pageSize:'20',q:$('#utilityQuery').value}));if(request!==generation)return;const rows=payload.records||[],meta=payload.meta||{total:rows.length,totalPages:1};$('#utilitySummary').innerHTML=payload.summary?.totalCents!==undefined?`<p>本次筛选合计：<strong>${money(payload.summary.totalCents)}</strong></p>`:'';$('#utilityRows').innerHTML=rows.map(r=>`<article class="listitem"><div style="min-width:0"><h3>${esc(r.title||cfg.name)} ${r.pinned?'<span class="badge">已置顶</span>':''} ${r.status?utilityStatus(r.status,m):''}</h3>${cfg.fields.filter(f=>f.key!=='title').map(f=>`<p style="white-space:pre-wrap;overflow-wrap:anywhere"><span class="muted">${esc(f.label)}：</span>${esc(displayValue(f,r[f.key]))}</p>`).join('')}</div><div class="row">${(r.allowedActions||[]).filter(a=>a!=='export'||cfg.exportable).map(a=>`<button class="btn" data-utility-action="${esc(a)}" data-utility-id="${esc(r.id)}">${esc(actionTitles[a]||a)}</button>`).join('')}</div></article>`).join('')||'<div class="empty">暂无匹配记录。</div>';$('#utilityPager').innerHTML=`<span class="muted">共 ${meta.total} 条 · 第 ${page} / ${Math.max(1,meta.totalPages)} 页</span><button class="btn" id="utilityPrev" ${page===1?'disabled':''}>上一页</button><button class="btn" id="utilityNext" ${page>=meta.totalPages?'disabled':''}>下一页</button>`;$('#utilityPrev').onclick=()=>{page--;draw()};$('#utilityNext').onclick=()=>{page++;draw()};document.querySelectorAll('[data-utility-action]').forEach(b=>b.onclick=async()=>{const r=rows.find(v=>v.id===b.dataset.utilityId),action=b.dataset.utilityAction;if(action==='edit'){edit(r);return}if(['archive','publish','unpublish'].includes(action)&&!await askConfirm('确认'+actionTitles[action]+'此记录？'))return;b.disabled=true;try{if(action==='export'){const file=await api(base+'/'+r.id+'/export');const url=URL.createObjectURL(new Blob([file.content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=file.filename||'校园资料.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已生成下载文件')}else{await api(base+'/'+r.id+'/action','POST',{action,version:r.version});toast('操作已保存');draw()}}catch(e){toast(e.message)}finally{b.disabled=false}})}catch(e){$('#utilityRows').innerHTML=`<div class="error">${esc(e.message)}</div>`}};if($('#utilityNew'))$('#utilityNew').onclick=()=>edit();$('#utilitySearch').onclick=()=>{page=1;draw()};$('#utilityQuery').onkeydown=e=>{if(e.key==='Enter'){page=1;draw()}};draw(first)}

function extensionStatus(status,module){return '<span class="service-status">'+esc(module==='jobs'&&status==='ACCEPTED'?'已录用':module==='leaves'&&status==='RETURNED'?'已销假':serviceLabels[status]||labels[status]||status)+'</span>'}
function extensionActionLabel(action,module){if(action==='return')return module==='leaves'?'返校销假':'办理归还';return extensionActionTitles[action]||action}

function utilityStatus(status,module){const text=status==='ACTIVE'?(module==='tasks'?'进行中':module==='expenses'?'已记录':'已保存'):serviceLabels[status]||({DRAFT:'草稿',PUBLISHED:'已发布',ARCHIVED:'已归档'})[status]||labels[status]||status;return '<span class="service-status">'+esc(text)+'</span>'}
